// Generated by `just generate` from `src/plugins/claudetto/slices/goal/domain/command.ts`. Edit the source and run `just generate`.
// The rules of the `/goal` command: the flags, the move between steps, and the status text.
// The adapter reads and writes the state and starts the loop, and this module decides.

import { label, planGrowth, type Spend } from "./loop.ts";
import type { Controls, Goal } from "./state.ts";

/** The condition without its flags, and the controls that the flags set. */
export type Parsed = { condition: string; controls: Partial<Controls> };

/** The time in milliseconds of `text`: `HH:MM` is the next such time, a date alone is midnight local time, and `NaN` is no time. */
const untilOf = (text: string, now: number): number => {
  if (!/^\d{1,2}:\d{2}$/.test(text)) {
    return Date.parse(/^\d{4}-\d\d-\d\d$/.test(text) ? `${text}T00:00` : text);
  }
  const [hours = 0, minutes = 0] = text.split(":").map(Number);
  if (hours > 23 || minutes > 59) return Number.NaN;
  const date = new Date(now);
  date.setHours(hours, minutes, 0, 0);
  if (date.getTime() <= now) date.setDate(date.getDate() + 1);
  return date.getTime();
};

/**
 * Splits the text after `/goal` into the condition and the controls of the flags `--max-turns N`, `--budget $X` or `N%`, `--until TIME`, and `--stall N`.
 * A flag starts a word. A value must be a number above 0, and a time must be valid, or the result is an error line.
 */
export const parseArgs = (args: string, now: number): Parsed | string => {
  const flags = new Map<string, string>();
  const condition = args
    .replace(
      /(^|\s)--(max-turns|budget|stall|until)[ =](\S+)/g,
      (_, space, key, value) => {
        flags.set(key, value);
        return space;
      },
    )
    .trim();
  const c: { -readonly [K in keyof Controls]?: Controls[K] } = {};
  for (const [key, value] of flags) {
    const isUntil = key === "until";
    const n = isUntil
      ? untilOf(value, now)
      : Number(value.replace(/^\$|%$/g, ""));
    if (isUntil && Number.isFinite(n) && n <= now) {
      return `The time \`${value}\` of \`--until\` is not after now.`;
    }
    if (!Number.isFinite(n) || (!isUntil && n <= 0)) {
      return `The value \`${value}\` of \`--${key}\` is not valid.`;
    }
    if (key === "max-turns") c.maxTurns = n;
    else if (key === "stall") c.stall = n;
    else if (isUntil) c.until = n;
    else c.budget = value.endsWith("%") ? { percent: n } : { usd: n };
  }
  return { condition, controls: c };
};

/** The new goal (`null` clears it), a line to show, and whether the loop starts a turn now. */
export type Change = { goal: Goal | null; say: string; start: boolean };

/** The goal at step `index` with the counts reset and a `note` in the log, or the end of the goal. */
const moveTo = (
  goal: Goal,
  index: number,
  note: string,
  now: number,
): Change =>
  index >= goal.steps.length
    ? { goal: null, say: "The goal is done.", start: false }
    : {
        goal: {
          ...goal,
          step: index,
          results: [],
          stalled: 0,
          paused: false,
          log: [...goal.log, { at: now, note }],
        },
        say: `${note}.`,
        start: true,
      };

/** The change that the word `pause`, `resume`, `skip`, or `step` (with `arg`) makes to `goal`. `usd` is the cost of the session now, and `percents` is its percent of each plan limit by kind. */
export const change = (
  goal: Goal,
  word: string,
  arg: string,
  now: number,
  usd: number,
  percents: Readonly<Record<string, number>> = {},
): Change => {
  const at = goal.step + 1;
  if (word === "pause") {
    return {
      goal: { ...goal, paused: true },
      say: "Goal paused.",
      start: false,
    };
  }
  if (word === "resume") {
    if (!goal.paused)
      return { goal, say: "The goal is not paused.", start: false };
    // A resumed goal counts its turns, its cost, and its plan percents from the resume, or it would stop at once.
    const fresh = {
      ...goal,
      turns: 0,
      spentUsd: 0,
      lastUsd: usd,
      basePercents: percents,
    };
    return moveTo(fresh, goal.step, `Resumed at step ${at}`, now);
  }
  if (word === "skip") return moveTo(goal, at, `Skipped step ${at}`, now);
  const n = Number(arg);
  if (Number.isInteger(n) && n >= 1 && n <= goal.steps.length) {
    return moveTo(goal, n - 1, `Moved to step ${n}`, now);
  }
  return {
    goal,
    say: `Use \`/goal step N\`, with N from 1 to ${goal.steps.length}.`,
    start: false,
  };
};

/** The status of `goal`: the step, each check with its last result, and the budget. */
export const statusText = (goal: Goal, spend: Spend): string => {
  const { title, checks } = goal.steps[goal.step] ?? { title: "", checks: [] };
  const lines = checks.map((check, i) => {
    const result = goal.results[i];
    const state = result ? (result.pass ? "pass" : "fail") : "not run";
    return `- ${label(check)}: ${state}`;
  });
  const { budget } = goal;
  const limits = [
    goal.maxTurns === undefined
      ? ""
      : `turns ${goal.turns} of ${goal.maxTurns}`,
    budget?.usd === undefined
      ? ""
      : `cost $${goal.spentUsd.toFixed(2)} of $${budget.usd}`,
    budget?.percent === undefined
      ? ""
      : `plan ${planGrowth(spend.percents, goal.basePercents)}% of ${budget.percent}%`,
  ].filter(Boolean);
  const head = `Goal step ${goal.step + 1} of ${goal.steps.length}: ${title}${goal.paused ? " (paused)" : ""}`;
  return [head, ...lines, limits.join(", ")].filter(Boolean).join("\n");
};
